<script setup>import{useForm}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';import SeoHead from'../../Components/SeoHead.vue';const props=defineProps({service:Object}),form=useForm({name:'',email:'',phone:'',preferred_date:'',message:''});const submit=()=>form.post(`/services/${props.service.slug}/inquiry`,{preserveScroll:true,onSuccess:()=>form.reset()});</script><template><AppLayout><SeoHead :title="service.meta_title||service.name" :description="service.meta_description||service.short_description" :image="service.image_url"/><div class="container-shell py-8"><div class="grid gap-8 lg:grid-cols-2"><div><img :src="service.image_url" :alt="service.name" class="card aspect-[4/3] w-full object-cover"><p class="mt-5 text-xs font-black uppercase text-prinx-600">{{service.category?.name}}</p><h1 class="mt-2 text-3xl font-black">{{service.name}}</h1><p class="mt-3 leading-7 text-slate-600 whitespace-pre-line">{{service.description}}</p><p class="mt-5 font-black">{{service.price_label||'Request a quotation'}}</p><p v-if="service.duration" class="mt-1 text-sm text-slate-500">Typical time: {{service.duration}}</p></div><form class="card p-5" @submit.prevent="submit"><h2 class="text-xl font-black">Request this service</h2><div class="mt-4 grid gap-4"><div><label class="label">Name</label><input v-model="form.name" class="input"><p class="error">{{form.errors.name}}</p></div><div><label class="label">Email</label><input v-model="form.email" type="email" class="input"></div><div><label class="label">Phone</label><input v-model="form.phone" class="input"></div><div><label class="label">Preferred date</label><input v-model="form.preferred_date" type="date" class="input"></div><div><label class="label">Message</label><textarea v-model="form.message" class="input" rows="5"></textarea></div><button class="btn-primary" :disabled="form.processing">Send request</button></div></form></div></div></AppLayout></template>
